import frappe
MARK='<!-- INVENTORY PRINT DEFAULT v2 -->'
FORMATS={'Receipt Inspection Report':'Purchase Receipt','Acceptance Decision':'Quality Inspection','Material Issue Authorization':'Material Request','Stock Transfer Authorization':'Stock Entry','Stock Handover Record':'Stock Handover','Material Return Record':'Stock Entry','Asset Custody Record':'Asset Custody','Asset Return Record':'Asset Custody','Physical Verification Record':'Physical Verification','Asset Incident Record':'Asset Incident','Variance Resolution':'Physical Verification'}
HTML=MARK+'''{% set company=frappe.get_doc("Company",doc.company) if doc.get("company") else None %}{% set primary=(company.custom_print_document_header_color if company and company.meta.has_field("custom_print_document_header_color") and company.custom_print_document_header_color else (company.custom_primary_color if company and company.meta.has_field("custom_primary_color") and company.custom_primary_color else '#176b87')) %}<div style="font-family:Arial,Tahoma,sans-serif;font-size:10px;color:#263238"><div style="border-bottom:3px solid {{ primary }};padding:10px 0"><table width="100%"><tr><td>{% if company and company.company_logo %}<img src="{{ company.company_logo }}" style="max-height:55px;max-width:180px">{% endif %}</td><td style="text-align:right"><h2 style="color:{{ primary }}">{{ _(doc.doctype) }}</h2><b>{{ doc.name }}</b></td></tr></table></div>{% for field in doc.meta.fields %}{% set value=doc.get(field.fieldname) %}{% if field.fieldtype=="Table" and value %}<h3 style="color:{{ primary }}">{{ _(field.label) }}</h3><table width="100%" style="border-collapse:collapse"><thead><tr>{% for df in frappe.get_meta(field.options).fields %}{% if df.in_list_view and df.fieldname!="page_break" %}<th style="border:1px solid #ccc;padding:4px">{{ _(df.label) }}</th>{% endif %}{% endfor %}</tr></thead><tbody>{% for row in value %}<tr>{% for df in frappe.get_meta(field.options).fields %}{% if df.in_list_view and df.fieldname!="page_break" %}<td style="border:1px solid #ccc;padding:4px">{{ frappe.format_value(row.get(df.fieldname),df,row) }}</td>{% endif %}{% endfor %}</tr>{% if row.page_break %}</tbody></table><div style="page-break-after:always"></div><table width="100%"><tbody>{% endif %}{% endfor %}</tbody></table>{% elif field.fieldtype not in ["Section Break","Column Break","Tab Break","Table","HTML","Button","Signature"] and value not in [None,""] %}<div style="display:inline-block;width:48%;vertical-align:top;padding:3px"><b>{{ _(field.label) }}:</b> {{ frappe.format_value(value,field,doc) }}</div>{% endif %}{% endfor %}<table width="100%" style="margin-top:28px"><tr><td>Prepared By<br><br>________________</td><td>Reviewed By<br><br>________________</td><td>Approved By<br><br>________________</td></tr></table></div>'''
def provision_print_formats():
 for name,dt in FORMATS.items():
  if not frappe.db.exists('Print Format',name):frappe.get_doc({'doctype':'Print Format','name':name,'doc_type':dt,'print_format_type':'Jinja','html':HTML,'custom_format':1,'disabled':0}).insert(ignore_permissions=True)
